def related(title, links):
    a=''.join(f'<a href="{u}" class="c-related-link">{t}</a>' for t,u in links)
    return f'<section class="c-related"><div class="c-container"><p class="c-related-title">{title}</p><div class="c-related-links">{a}</div></div></section>'

def crumbs(items):
    out=['<nav class="c-breadcrumb" aria-label="Fil d\'Ariane">']
    for i,(t,u) in enumerate(items):
        if i: out.append('<span class="c-crumb-sep">/</span>')
        out.append(f'<a href="{u}" class="c-crumb-link">{t}</a>' if u else f'<span class="c-crumb-current">{t}</span>')
    out.append('</nav>')
    return ''.join(out)
